package com.smitnk.sketcher.model

import android.graphics.Bitmap
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableFloatStateOf
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.compose.runtime.snapshots.SnapshotStateList
import androidx.compose.ui.graphics.ImageBitmap
import com.smitnk.sketcher.image.Stroke

/** Origin of a layer: generated by the pipeline (replaced on re-generate) or drawn/added by the user. */
enum class LayerKind { AUTO_OUTLINE, AUTO_SHADING, AUTO_FILL, MANUAL }

class Layer(val id: Long, name: String) {
    /** Do not reorder entries: the ordinal is persisted by ProjectCodec. */
    var kind: LayerKind = LayerKind.MANUAL
    var name by mutableStateOf(name)
    val strokes = mutableStateListOf<Stroke>()
    var visible by mutableStateOf(true)
    var opacity by mutableFloatStateOf(1f)
    var locked by mutableStateOf(false)

    /** Whether this layer takes part in the draw-along animation. */
    var inAnimation by mutableStateOf(true)

    /** Animation order: lower plays first; ties keep list (bottom-to-top) order. */
    var animPriority by mutableIntStateOf(0)

    /**
     * Pencil-reveal ink (ARGB_8888, ink-black, alpha = ink, drawing size). When set, [strokes] are only reveal
     * paths (width [revealWidthPx]) that uncover the texture as they animate; they are never drawn themselves.
     */
    var inkTexture: Bitmap? = null
        set(v) { field = v; inkRev++ }

    var revealWidthPx by mutableFloatStateOf(0f)

    /** Bumped whenever [inkTexture] changes (set or erased in place) so caches and the screen redraw. */
    var inkRev by mutableIntStateOf(0)

    fun totalLength(): Float {
        var total = 0f
        for (s in strokes) total += s.length
        return total
    }
}

/**
 * One page of the animation: its own layers, reference photo and draw-along length.
 * Layer ids are unique across the whole [Project] (see [Project.newLayer]).
 */
class Frame(val id: Long) {
    val layers = mutableStateListOf<Layer>()
    var selectedIndex by mutableIntStateOf(0)

    /** Optional reference photo (same size as the canvas). Never part of exports. */
    var background by mutableStateOf<Bitmap?>(null)
    var backgroundVisible by mutableStateOf(true)
    var backgroundOpacity by mutableFloatStateOf(1f)

    /** Draw-along animation length of this frame in seconds (the live value of the open frame is AnimationController's). */
    var durationSec by mutableFloatStateOf(DEFAULT_DURATION_SEC)

    // --- generation bookkeeping owned by SketchViewModel (per frame, not persisted)
    /** The imported photo this frame is generated from (may differ in size from [background]). */
    var sourceBitmap: Bitmap? = null
    var sourceSerial = 0
    var autoSource = 0

    // --- thumbnail cache for the frame strip (render + signature owned by ui/frames)
    var thumbnail by mutableStateOf<ImageBitmap?>(null)
    var thumbSig = 0L

    companion object {
        const val DEFAULT_DURATION_SEC = 12f
    }
}

class Project {
    var width by mutableIntStateOf(1024)
    var height by mutableIntStateOf(1024)

    /** Per-project rendering style (paper, misregistration, post filter...). Persisted by ProjectCodec v5. */
    var look by mutableStateOf(com.smitnk.sketcher.look.LookSettings())

    val frames = mutableStateListOf<Frame>()
    var currentFrameIndex by mutableIntStateOf(0)

    private var nextId = 1L
    private var nextFrameId = 1L

    init {
        frames.add(newFrame())
    }

    /** The frame being edited. Everything below (layers, photo, selection) operates on it. */
    val currentFrame: Frame
        get() = frames[currentFrameIndex.coerceIn(0, frames.lastIndex)]

    val layers: SnapshotStateList<Layer>
        get() = currentFrame.layers

    var selectedIndex: Int
        get() = currentFrame.selectedIndex
        set(v) { currentFrame.selectedIndex = v }

    /** Optional reference photo of the current frame. Never part of exports. */
    var background: Bitmap?
        get() = currentFrame.background
        set(v) { currentFrame.background = v }

    var backgroundVisible: Boolean
        get() = currentFrame.backgroundVisible
        set(v) { currentFrame.backgroundVisible = v }

    var backgroundOpacity: Float
        get() = currentFrame.backgroundOpacity
        set(v) { currentFrame.backgroundOpacity = v }

    val selectedLayer: Layer?
        get() = layers.getOrNull(selectedIndex)

    fun newLayer(name: String): Layer = Layer(nextId++, name)

    /** A fresh, empty frame with a new unique id (not added to [frames]). */
    fun newFrame(): Frame = Frame(nextFrameId++)

    /** A frame carrying a persisted id (keeps per-frame files stable); later new ids never collide with it. */
    fun frameWithId(id: Long): Frame {
        if (id >= nextFrameId) nextFrameId = id + 1
        return Frame(id)
    }

    /** Throws all frames away and leaves one empty frame (no layers yet). */
    fun resetFrames() {
        frames.clear()
        frames.add(newFrame())
        currentFrameIndex = 0
    }

    /** Deep copy of [src] with new frame/layer ids (strokes are immutable and shared; ink textures are copied). */
    fun copyFrame(src: Frame): Frame {
        val f = newFrame()
        for (l in src.layers) {
            val c = newLayer(l.name)
            c.kind = l.kind
            c.visible = l.visible
            c.opacity = l.opacity
            c.locked = l.locked
            c.inAnimation = l.inAnimation
            c.animPriority = l.animPriority
            c.strokes.addAll(l.strokes.toList())
            c.revealWidthPx = l.revealWidthPx
            c.inkTexture = l.inkTexture?.takeIf { !it.isRecycled }?.copy(Bitmap.Config.ARGB_8888, true)
            f.layers.add(c)
        }
        f.selectedIndex = src.selectedIndex
        f.background = src.background
        f.backgroundVisible = src.backgroundVisible
        f.backgroundOpacity = src.backgroundOpacity
        f.durationSec = src.durationSec
        f.sourceBitmap = src.sourceBitmap
        f.sourceSerial = src.sourceSerial
        f.autoSource = src.autoSource
        return f
    }
}
